// src/App.js - Versión definitiva y funcional
import React, { useState, useEffect } from 'react';
import { useAuth } from './context/AuthContext';
import Auth from './components/Auth';
import axios from 'axios';

const API_URL = 'https://backend-control-tanque-production-154a.up.railway.app';

function App() {
  const { user, logout, isAuthenticated, loading } = useAuth();
  const [devices, setDevices] = useState([]);
  const [selectedDevice, setSelectedDevice] = useState(null);
  const [history, setHistory] = useState([]);
  const [status, setStatus] = useState(null);
  const [message, setMessage] = useState({ text: '', type: '' });
  const [view, setView] = useState('config');
  const [loadingAction, setLoadingAction] = useState(false);

  // Configuración
  const [tankHeight, setTankHeight] = useState('');
  const [minLevel, setMinLevel] = useState('');
  const [maxLevel, setMaxLevel] = useState('');
  const [newDeviceId, setNewDeviceId] = useState('');

  useEffect(() => {
    if (isAuthenticated) {
      fetchDevices();
    }
  }, [isAuthenticated]);

  useEffect(() => {
    if (selectedDevice && isAuthenticated) {
      fetchStatus(selectedDevice.deviceId);
      fetchHistory(selectedDevice.deviceId);
      setTankHeight(selectedDevice.tankHeight?.toString() || '');
      setMinLevel(selectedDevice.minLevel?.toString() || '');
      setMaxLevel(selectedDevice.maxLevel?.toString() || '');
    }
  }, [selectedDevice]);

  // Polling para actualizar datos
  useEffect(() => {
    if (view !== 'dashboard' || !selectedDevice) return;
    const interval = setInterval(() => {
      fetchStatus(selectedDevice.deviceId);
      fetchHistory(selectedDevice.deviceId);
    }, 3000);
    return () => clearInterval(interval);
  }, [view, selectedDevice]);

  const fetchDevices = async () => {
    try {
      const res = await axios.get(`${API_URL}/api/devices`);
      setDevices(res.data);
      if (res.data.length > 0 && !selectedDevice) {
        setSelectedDevice(res.data[0]);
      }
    } catch (err) {
      console.error(err);
    }
  };

  const fetchStatus = async (deviceId) => {
    try {
      const res = await axios.get(`${API_URL}/api/status/${deviceId}`);
      setStatus(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  const fetchHistory = async (deviceId) => {
    try {
      const res = await axios.get(`${API_URL}/api/history/${deviceId}`);
      setHistory(res.data);
    } catch (err) {
      console.error(err);
    }
  };

  const registerDevice = async () => {
    if (!newDeviceId.trim()) {
      setMessage({ text: 'Ingresa un ID de dispositivo', type: 'error' });
      return;
    }

    setLoadingAction(true);
    try {
      // Verificar si ya existe
      const existing = devices.find(d => d.deviceId === newDeviceId);
      if (existing) {
        setMessage({ text: `❌ El dispositivo ${newDeviceId} YA está registrado`, type: 'error' });
        setLoadingAction(false);
        return;
      }

      await axios.post(`${API_URL}/api/devices/register`, {
        deviceId: newDeviceId,
        name: 'Mi Tanque'
      });
      
      setMessage({ text: `✅ Dispositivo ${newDeviceId} registrado correctamente`, type: 'success' });
      setNewDeviceId('');
      await fetchDevices();
      
      setTimeout(() => setMessage({ text: '', type: '' }), 3000);
    } catch (err) {
      const errorMsg = err.response?.data?.error || 'Error al registrar';
      setMessage({ text: `❌ ${errorMsg}`, type: 'error' });
    } finally {
      setLoadingAction(false);
    }
  };

  const saveConfig = async () => {
    if (!selectedDevice) return;

    const height = parseFloat(tankHeight);
    const min = parseFloat(minLevel);
    const max = parseFloat(maxLevel);

    if (isNaN(height) || height <= 0) {
      setMessage({ text: 'Altura válida requerida', type: 'error' });
      return;
    }
    if (isNaN(min) || min < 0 || min > 100) {
      setMessage({ text: 'Nivel mínimo entre 0 y 100', type: 'error' });
      return;
    }
    if (isNaN(max) || max < 0 || max > 100) {
      setMessage({ text: 'Nivel máximo entre 0 y 100', type: 'error' });
      return;
    }
    if (min >= max) {
      setMessage({ text: 'El mínimo debe ser menor que el máximo', type: 'error' });
      return;
    }

    setLoadingAction(true);
    try {
      await axios.post(`${API_URL}/api/config`, {
        deviceId: selectedDevice.deviceId,
        minLevel: min,
        maxLevel: max,
        tankHeight: height
      });
      setMessage({ text: '✅ Configuración guardada', type: 'success' });
      setTimeout(() => setMessage({ text: '', type: '' }), 2000);
      setView('dashboard');
    } catch (err) {
      setMessage({ text: 'Error al guardar', type: 'error' });
    } finally {
      setLoadingAction(false);
    }
  };

  if (loading) {
    return <div style={{ textAlign: 'center', marginTop: 50 }}>Cargando...</div>;
  }

  if (!isAuthenticated) {
    return <Auth />;
  }

  // Pantalla de bienvenida - Registrar dispositivo
  if (devices.length === 0) {
    return (
      <div style={{ maxWidth: 500, margin: '50px auto', padding: 20, border: '1px solid #ccc', borderRadius: 10 }}>
        <h2 style={{ textAlign: 'center' }}>📟 Registrar Dispositivo</h2>
        {message.text && (
          <div style={{ padding: 10, marginBottom: 15, backgroundColor: message.type === 'error' ? '#ffebee' : '#e8f5e9', color: message.type === 'error' ? '#c62828' : '#2e7d32', borderRadius: 5 }}>
            {message.text}
          </div>
        )}
        <input
          type="text"
          placeholder="ID del ESP (ej: ESP_001)"
          value={newDeviceId}
          onChange={(e) => setNewDeviceId(e.target.value)}
          style={{ width: '100%', padding: 10, marginBottom: 15, border: '1px solid #ccc', borderRadius: 5 }}
        />
        <button
          onClick={registerDevice}
          disabled={loadingAction}
          style={{ width: '100%', padding: 10, backgroundColor: '#1976d2', color: 'white', border: 'none', borderRadius: 5, cursor: 'pointer' }}
        >
          {loadingAction ? 'Registrando...' : 'Registrar Dispositivo'}
        </button>
        <button onClick={logout} style={{ width: '100%', marginTop: 10, padding: 10, backgroundColor: '#f5f5f5', border: '1px solid #ccc', borderRadius: 5, cursor: 'pointer' }}>
          Cerrar Sesión
        </button>
      </div>
    );
  }

  if (!selectedDevice) {
    return <div style={{ textAlign: 'center', marginTop: 50 }}>Cargando dispositivo...</div>;
  }

  // Pantalla de CONFIGURACIÓN
  if (view === 'config') {
    return (
      <div style={{ maxWidth: 600, margin: '30px auto', padding: 20, border: '1px solid #ccc', borderRadius: 10 }}>
        <h2 style={{ textAlign: 'center' }}>⚙️ Configuración del Tanque</h2>
        <p style={{ textAlign: 'center', color: '#666', marginBottom: 20 }}>Dispositivo: {selectedDevice.deviceId}</p>

        {message.text && (
          <div style={{ padding: 10, marginBottom: 15, backgroundColor: message.type === 'error' ? '#ffebee' : '#e8f5e9', color: message.type === 'error' ? '#c62828' : '#2e7d32', borderRadius: 5 }}>
            {message.text}
          </div>
        )}

        <div style={{ marginBottom: 20 }}>
          <label style={{ display: 'block', marginBottom: 5 }}>📏 Altura del Tanque (cm)</label>
          <input
            type="number"
            value={tankHeight}
            onChange={(e) => setTankHeight(e.target.value)}
            style={{ width: '100%', padding: 10, border: '1px solid #ccc', borderRadius: 5 }}
            placeholder="Ej: 100"
          />
        </div>

        <div style={{ marginBottom: 20 }}>
          <label style={{ display: 'block', marginBottom: 5 }}>⬇️ Nivel Mínimo (%) - Encender bomba</label>
          <input
            type="number"
            value={minLevel}
            onChange={(e) => setMinLevel(e.target.value)}
            style={{ width: '100%', padding: 10, border: '1px solid #ccc', borderRadius: 5 }}
            placeholder="Ej: 20"
          />
          <input
            type="range"
            min="0"
            max="100"
            value={minLevel || 20}
            onChange={(e) => setMinLevel(e.target.value)}
            style={{ width: '100%', marginTop: 10 }}
          />
        </div>

        <div style={{ marginBottom: 20 }}>
          <label style={{ display: 'block', marginBottom: 5 }}>⬆️ Nivel Máximo (%) - Apagar bomba</label>
          <input
            type="number"
            value={maxLevel}
            onChange={(e) => setMaxLevel(e.target.value)}
            style={{ width: '100%', padding: 10, border: '1px solid #ccc', borderRadius: 5 }}
            placeholder="Ej: 80"
          />
          <input
            type="range"
            min="0"
            max="100"
            value={maxLevel || 80}
            onChange={(e) => setMaxLevel(e.target.value)}
            style={{ width: '100%', marginTop: 10 }}
          />
        </div>

        <button
          onClick={saveConfig}
          disabled={loadingAction}
          style={{ width: '100%', padding: 10, backgroundColor: '#1976d2', color: 'white', border: 'none', borderRadius: 5, cursor: 'pointer', marginBottom: 10 }}
        >
          {loadingAction ? 'Guardando...' : 'Guardar y ver Dashboard'}
        </button>
        <button onClick={logout} style={{ width: '100%', padding: 10, backgroundColor: '#f5f5f5', border: '1px solid #ccc', borderRadius: 5, cursor: 'pointer' }}>
          Cerrar Sesión
        </button>
      </div>
    );
  }

  // DASHBOARD
  const level = status?.level || 0;
  const pump = status?.pumpStatus || false;
  const currentMin = selectedDevice.minLevel || 20;
  const currentMax = selectedDevice.maxLevel || 80;

  const chartData = history.slice(-20).map(item => ({
    time: new Date(item.timestamp).toLocaleTimeString(),
    level: item.level
  }));

  const avg = history.length ? (history.reduce((a, b) => a + b.level, 0) / history.length).toFixed(0) : 0;
  const maxH = history.length ? Math.max(...history.map(h => h.level)) : 0;
  const minH = history.length ? Math.min(...history.map(h => h.level)) : 0;

  return (
    <div style={{ maxWidth: 1200, margin: '0 auto', padding: 20 }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
        <h1 style={{ margin: 0 }}>💧 Control de Tanque</h1>
        <div>
          <button onClick={() => setView('config')} style={{ marginRight: 10, padding: '8px 16px', cursor: 'pointer' }}>
            ⚙️ Configurar
          </button>
          <button onClick={logout} style={{ padding: '8px 16px', cursor: 'pointer' }}>
            Salir
          </button>
        </div>
      </div>

      {message.text && (
        <div style={{ padding: 10, marginBottom: 15, backgroundColor: message.type === 'error' ? '#ffebee' : '#e8f5e9', color: message.type === 'error' ? '#c62828' : '#2e7d32', borderRadius: 5 }}>
          {message.text}
        </div>
      )}

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20, marginBottom: 20 }}>
        <div style={{ border: '1px solid #ccc', borderRadius: 10, padding: 15 }}>
          <h3>📊 Nivel Actual</h3>
          <div style={{ fontSize: 48, fontWeight: 'bold' }}>{Math.round(level)}%</div>
          <div style={{ height: 10, backgroundColor: '#e0e0e0', borderRadius: 5, marginTop: 10 }}>
            <div style={{ width: `${level}%`, height: '100%', backgroundColor: level > 80 ? '#f44336' : level < 20 ? '#ff9800' : '#4caf50', borderRadius: 5 }}></div>
          </div>
          <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 10 }}>
            <span>Mín: {currentMin}%</span>
            <span>Máx: {currentMax}%</span>
          </div>
        </div>

        <div style={{ border: '1px solid #ccc', borderRadius: 10, padding: 15 }}>
          <h3>🔌 Estado de la Bomba</h3>
          <div style={{ fontSize: 32, fontWeight: 'bold', color: pump ? '#4caf50' : '#f44336' }}>
            {pump ? 'ENCENDIDA' : 'APAGADA'}
          </div>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20, marginBottom: 20 }}>
        <div style={{ border: '1px solid #ccc', borderRadius: 10, padding: 15 }}>
          <h3>📈 Estadísticas</h3>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', textAlign: 'center' }}>
            <div><div style={{ fontSize: 24, fontWeight: 'bold' }}>{avg}%</div><span>Promedio</span></div>
            <div><div style={{ fontSize: 24, fontWeight: 'bold', color: '#f44336' }}>{maxH}%</div><span>Máximo</span></div>
            <div><div style={{ fontSize: 24, fontWeight: 'bold', color: '#ff9800' }}>{minH}%</div><span>Mínimo</span></div>
          </div>
        </div>

        <div style={{ border: '1px solid #ccc', borderRadius: 10, padding: 15 }}>
          <h3>📊 Historial</h3>
          {history.length > 0 ? (
            <div style={{ height: 200, overflowY: 'auto' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                <thead>
                  <tr><th>Hora</th><th>Nivel</th></tr>
                </thead>
                <tbody>
                  {chartData.slice().reverse().map((item, i) => (
                    <tr key={i}><td>{item.time}</td><td>{Math.round(item.level)}%</td></tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <p>Sin datos. Conecta tu ESP8266.</p>
          )}
        </div>
      </div>
    </div>
  );
}

export default App;